import pandas as pd
import numpy as np
from itertools import combinations

np.random.seed(42)
df = pd.read_csv('/app/bn_sample_10k.csv')
cols = list(df.columns)  # U,Y,R,D,M
X = df[cols].values
n = X.shape[0]
idx = {c:i for i,c in enumerate(cols)}
Sigma = np.cov((X - X.mean(axis=0)).T)

def partial_corr(i, j, S):
    T = [i, j] + list(S)
    Sig = Sigma[np.ix_(T, T)]
    Om = np.linalg.inv(Sig)
    return -Om[0,1] / np.sqrt(Om[0,0]*Om[1,1])

# 1) Recover DAG skeleton via CI tests
undirected = []
for a, b in combinations(range(len(cols)), 2):
    others = [k for k in range(len(cols)) if k not in (a,b)]
    min_pc = 1.0
    for r in range(len(others)+1):
        for S in combinations(others, r):
            pc = abs(partial_corr(a, b, S))
            if pc < min_pc:
                min_pc = pc
    if min_pc > 0.1:
        undirected.append((cols[a], cols[b]))

# Orient: U has no parents (U is parent); else first-alphabet letter = child
directed = []
for a, b in undirected:
    if 'U' in (a, b):
        other = b if a == 'U' else a
        directed.append((other, 'U'))
    else:
        first, second = sorted([a, b])
        directed.append((first, second))
seen=set(); final_edges=[]
for to,frm in directed:
    if (to,frm) not in seen:
        seen.add((to,frm)); final_edges.append((to,frm))

with open('/app/learned_dag.csv','w') as f:
    f.write("to,from\n")
    for to,frm in sorted(final_edges):
        f.write(f"{to},{frm}\n")
print("learned_dag.csv:")
for to,frm in sorted(final_edges): print(f"  {to},{frm}")

parents_of = {c:[] for c in cols}
for to,frm in final_edges: parents_of[to].append(frm)

def fit_ols(target, par):
    y = X[:, idx[target]]
    A = np.ones((n,1)) if not par else np.column_stack([np.ones(n), X[:,[idx[c] for c in par]]])
    coef,*_ = np.linalg.lstsq(A, y, rcond=None)
    var = float(np.var(y - A@coef, ddof=1))
    return coef, var

model = {}
for c in cols:
    model[c] = dict(par=parents_of[c], coef=fit_ols(c, parents_of[c])[0], var=fit_ols(c, parents_of[c])[1])

# 3) do(Y=0.0): remove incoming edges to Y, fix Y=0.0
intervened_edges = [(to,frm) for to,frm in final_edges if to != 'Y']
with open('/app/intervened_dag.csv','w') as f:
    f.write("to,from\n")
    for to,frm in sorted(intervened_edges):
        f.write(f"{to},{frm}\n")
print("\nintervened_dag.csv:")
for to,frm in sorted(intervened_edges): print(f"  {to},{frm}")

# 5) sample 10k from intervened BN (topological order U,Y,R,D,M)
NS = 10000
out = {c: np.zeros(NS) for c in cols}
for c in cols:
    par = model[c]['par']; coef = model[c]['coef']; var = model[c]['var']
    mu = coef[0]
    for i,p in enumerate(par):
        mu = mu + coef[i+1]*out[p]
    if c == 'Y':
        out[c] = 0.0  # do(Y=0.0) exact intervention
    else:
        out[c] = mu + np.random.normal(0, np.sqrt(var), NS)

res = pd.DataFrame(out, columns=cols)
res.to_csv('/app/final_bn_sample.csv', index=False)
print("\nfinal_bn_sample.csv saved, shape", res.shape)
print(res.describe().round(3))
